export const libraryTopics = [
  a('homepage-scope','find-products','home','fashion',
    ['Forsiden: vis hva butikken faktisk selger','Homepage: communicate the actual catalog'],
    ['Vis ulike relevante innganger til sortimentet. Et stort kampanjebilde skal ikke få hele butikken til å se ut som én produktserie.','Show several relevant catalog entry points. A large campaign image should not make the whole store look like one product line.'],
    ['En ny kunde som bare ser jeans, kan overse at butikken også har gensere og treningstøy.','A new shopper seeing only jeans may miss sweaters and activewear.'],
    ['Bruk representative kategorier i brede butikker; få produkter kan vises direkte. Prioriter retning før flere kampanjer.','Use representative categories for broad stores; a small catalog can be shown directly. Prioritize direction before more promotions.'],
    ['ReAI leverer publiserte samlinger; nettsiden velger rekkefølge, bilder og forklarende lenketekst.','ReAI delivers published collections; the site chooses order, images and explanatory link text.'],
    ['Famme viser tre fiktive samlinger, ikke hele Famme sitt virkelige sortiment.','Famme shows three fixture collections, not its complete real catalog.'],
    [['Finn jeans og gensere fra forsiden uten å bruke søk.','Find jeans and layers from the homepage without search.'],['Åpne et kolleksjonskort: overskriften skal bekrefte hvor du kom.','Open a collection card: the heading should confirm your destination.'],['På mobil: kontroller at kolleksjonene også kan finnes under banneret.','On mobile, check collections remain discoverable below the banner.']],['navigation','category-intermediary']),
  a('navigation-labels','find-products','nav','fashion',
    ['Navigasjonsnavn som kunden forstår','Navigation labels shoppers understand'],
    ['Bruk navn på produkter og behov i navigasjonen. Kreative kampanjenavn trenger en forklaring på hva lenken inneholder.','Use product and need-based navigation labels. Creative campaign names need an explanation of what the link contains.'],
    ['Et navn som bare ansatte kjenner, gjør kunden avhengig av å prøve alle lenkene.','An internal-only name makes shoppers try every link.'],
    ['Be nye kunder sortere produkter med egne ord før du gjør organisasjonskartet til meny.','Ask new shoppers to group products in their own words before turning an organization chart into navigation.'],
    ['Samlingens navn kan komme fra ReAI. Redaksjonelle navigasjonsnavn eies av nettstedet og må passe innholdet.','Collection names can come from ReAI. Editorial navigation labels belong to the site and must match the content.'],
    ['Softy er et serienavn; testeksemplet forklarer produktutvalget ved samlingen.','Softy is a range name; the fixture explains the collection contents.'],
    [['Be en deltaker finne en genser og noter hvilken menytittel de velger.','Ask a participant to find a sweater and observe their chosen label.'],['Sammenlign lenken med samlingens overskrift og varer.','Compare the link with the collection heading and items.'],['Bytt språk: produktbetydningen skal beholdes.','Switch languages: retain the product meaning.']],['homepage-scope','mobile-navigation']),
  a('category-intermediary','find-products','category','fashion',
    ['Kategoriforside eller direkte produktliste?','Category landing page or direct product list?'],
    ['En kategoriforside skal hjelpe kunden å velge en meningsfull undergruppe, med en tydelig vei til alle produktene.','A category landing page should help shoppers choose a meaningful subgroup, with a clear route to all products.'],
    ['En ekstra side med bare tre varer gir arbeid; hundrevis av ulike varer kan derimot trenge veiledning.','An extra page for three items creates work; hundreds of dissimilar items may need guidance.'],
    ['Bruk mellomnivåer ved brede sortimenter. Små, ensartede samlinger bør ofte åpne listen direkte.','Use intermediate levels for broad assortments. Small, uniform collections should often open the list directly.'],
    ['Samlinger fra ReAI er datagrunnlaget; et underkategorihierarki må defineres av virksomheten.','ReAI collections provide the data; the merchant must define any subcategory hierarchy.'],
    ['Famme-eksemplet går direkte til små lister. Det bygger ingen automatisk kategoritaksonomi.','The Famme fixture opens small lists directly. It builds no automatic category taxonomy.'],
    [['Åpne Softy: kom direkte til varer, ikke en tom veiledningsside.','Open Softy: reach products, not an empty guidance page.'],['Skisser et bredt sortiment: behold en vei til se alle.','Sketch a broad catalog: keep a view-all path.'],['Test om en ekstra kategori faktisk hjelper en ny kunde.','Test whether an additional category actually helps a new shopper.']],['navigation','homepage-scope']),
  a('mobile-navigation','find-products','nav','fashion',
    ['Mobilmeny med tydelige produktinnganger','Mobile menus with clear product entry points'],
    ['La produktkategorier være lette å finne når menyen åpnes. Lukking skal være like lett som åpning.','Make product categories easy to find when opening the menu. Closing should be as easy as opening.'],
    ['En stor om oss-seksjon eller skjult produktmeny skyver kjøpsoppgaven ned.','A large about section or hidden product menu pushes the shopping task away.'],
    ['Behold kontakt og hjelpelinker, men skill dem visuelt fra kategoriene. Ikke stol på hover på mobil.','Keep contact and help links, but distinguish them visually from categories. Never rely on hover on mobile.'],
    ['Nettsiden bygger meny og fokusstyring. Samlinger er lesbare fra Site API; ikke legg hemmelige administrasjonslenker her.','The site owns menu and focus behavior. Collections are readable from Site API; keep private administration links out.'],
    ['De egendefinerte designmenyene støtter Escape og returnerer fokus til menyknappen.','Custom design menus support Escape and return focus to the menu button.'],
    [['Åpne Meny ved 390 px og finn en kolleksjon.','Open Menu at 390 px and find a collection.'],['Trykk Escape: menyen lukkes og knappen får fokus.','Press Escape: the menu closes and its button receives focus.'],['Åpne en kategori med tastaturet; menyen skal lukkes.','Open a category using the keyboard; the menu should close.']],['navigation-labels','keyboard-dialogs']),
  a('search-visibility','find-products','persist','discovery',
    ['Synlig søk og en redigerbar søketekst','Visible search with an editable query'],
    ['Gi søkefeltet et navn, en send-knapp og den siste søketeksten. Kunden skal kunne forbedre søket uten å begynne på nytt.','Give search a label, submit button and the previous query. Shoppers should refine a search without starting over.'],
    ['Et tomt felt etter et mislykket søk fjerner forklaringen på resultatene.','An empty field after an unsuccessful search removes the explanation for the results.'],
    ['Søk passer større kataloger og eksakte varer. En liten gavekortbutikk kan bruke direkte produktvalg.','Search suits larger catalogs and exact items. A small gift-card store can use direct selection.'],
    ['Laben beholder søket i URL-en. Produksjonssøk må definere hvilke publiserte felt som søkes.','The lab retains the query in its URL. Production search must define the published fields it searches.'],
    ['Laben søker bare i tre fiktive produkter og to hjelpesvar.','The lab searches only three fictional products and two help answers.'],
    [['Søk etter blue 500 og kontroller at teksten blir stående.','Search blue 500 and check the text remains.'],['Rediger 500 til 350 uten å tømme hele søket.','Edit 500 to 350 without clearing the query.'],['Bruk Tilbake: forrige søk og resultat skal gjenopprettes.','Use Back: restore the previous query and results.']],['search','no-results-recovery']),
  a('search-synonyms','find-products','search','discovery',
    ['Synonymer i produktsøk uten falske treff','Search synonyms without misleading matches'],
    ['Knytt kundens ord til dokumenterte produkttyper og egenskaper. Et synonym skal utvide språkforståelsen, ikke finne på en funksjon.','Map shopper vocabulary to documented product types and attributes. Synonyms should bridge language, not invent functionality.'],
    ['Travel cup og termokopp kan beskrive samme type; vanntett og vannavvisende betyr forskjellige ting.','Travel cup and termokopp may describe the same type; waterproof and water-resistant mean different things.'],
    ['Start med et lite, vedlikeholdt aliasregister. Bruk henvendelser og oppgavetester til å finne mangler.','Start with a small maintained alias list. Use support questions and task tests to identify gaps.'],
    ['Site API leverer produktfelt. Søkeindeks og synonymregler er butikkens integrasjonsvalg.','Site API supplies product fields. Search indexing and synonym rules are store integration choices.'],
    ['Laben har eksplisitte aliaser; den viser ingen innebygd ReAI søkemotor.','The lab has explicit aliases; it demonstrates no built-in ReAI search engine.'],
    [['Søk travel cup og sammenlign med termokopp.','Search travel cup and compare with termokopp.'],['Søk blue 500: egenskapene må finnes på samme variant.','Search blue 500: attributes must belong to the same variant.'],['Legg ikke til medisinske eller tekniske løfter som synonymer.','Do not add medical or technical promises as synonyms.']],['query-types','search-typos']),
  a('search-typos','find-products','typo','discovery',
    ['Skrivefeil: foreslå retting, behold kundens søk','Typos: suggest corrections and keep the query'],
    ['Vis et gjenkjennelig rettingsforslag ved kjente skrivefeil. Behold originalteksten til kunden selv velger forslaget.','Offer a recognizable correction for known typos. Retain the original query until the shopper chooses it.'],
    ['Et nulltreff på termokop kan feilaktig se ut som butikken ikke selger kopper.','Zero results for termokop can suggest that the store sells no mugs.'],
    ['Små kataloger kan bruke en kontrollert ordliste. SKU og modellnummer bør ikke rettes med tilfeldig stavegjetting.','Small catalogs can use a controlled dictionary. Avoid guessing corrections for SKUs and model numbers.'],
    ['Laben bruker en liten aliasliste; en større søketjeneste trenger kvalitetstester per språk.','The lab uses a small alias list; a larger search service needs quality tests per language.'],
    ['Det finnes bare navngitte rettinger, ingen generell fuzzy- eller AI-søketjeneste.','Only named corrections exist, not a general fuzzy or AI search service.'],
    [['Søk termokop: se et valgfritt termokopp-forslag.','Search termokop: see an optional termokopp suggestion.'],['Velg rettingen: felt og URL skal følge det valgte ordet.','Choose the correction: update the field and URL.'],['Søk en ukjent SKU: ikke erstatt den med et annet produktnummer.','Search an unknown SKU: never substitute a different product number.']],['autocomplete','no-results-recovery']),
  a('search-scope','find-products','scope','discovery',
    ['Søkeområde: produkter, hjelp eller hele innholdet','Search scope: products, help or all content'],
    ['Vis hvilket innhold søket gjelder. Kunden skal kunne utvide området uten å miste søketeksten.','Show what the search covers. Let shoppers widen its scope without losing the query.'],
    ['Et søk etter retur i et skjult produktområde kan gi null selv om hjelpesvaret finnes.','A returns query in an unnoticed product scope can return zero despite available help.'],
    ['Et enkelt søk kan vise produkter og hjelp sammen. Store kataloger kan tilby eksplisitt områdevalg.','A simple search can show products and help together. Large catalogs may offer explicit scopes.'],
    ['Katalog og redaksjonelt hjelpeinnhold har forskjellige kilder. Merk hjelpesvar som innhold, ikke produkter.','Catalog and editorial help have different sources. Label help answers as content rather than products.'],
    ['Laben har tre områder med samme søketekst og URL-kontekst.','The lab has three scopes sharing the query and URL context.'],
    [['Søk returns med Produkter valgt: se forklaring og områdevalg.','Search returns with Products selected: see an explanation and scope choice.'],['Bytt til Alt: hjelpesvaret skal vises og teksten beholdes.','Switch to All: show the help answer and retain the query.'],['Bruk Tilbake: område og søketekst skal følge historikken.','Use Back: scope and query should follow browser history.']],['search-visibility','no-results-recovery']),
  a('no-results-recovery','find-products','empty','discovery',
    ['Nulltreff med konkrete veier videre','No results with useful recovery paths'],
    ['Forklar nulltreff uten å skylde på kunden. Tilby retting, et bredere område eller fjerning av begrensninger.','Explain zero results without blaming the shopper. Offer correction, a wider scope or removal of constraints.'],
    ['En tom liste gir verken forklaring eller neste steg. Tilfeldige anbefalinger løser ikke nødvendigvis søket.','An empty list provides neither explanation nor a next step. Random recommendations may not solve the query.'],
    ['Behold det kunden skrev. Vis få relevante forslag, og skill et nulltreff fra en teknisk feil.','Retain the typed query. Offer a few relevant paths and distinguish zero matches from technical failure.'],
    ['Feil fra Site API skal vises som utilgjengelige data, ikke et tomt sortiment eller fiktive erstatningsvarer.','Site API failure must appear as unavailable data, not an empty catalog or fixture replacement items.'],
    ['Søkelaben bruker lokal testdata. Ekte katalogfeil har egne feilsider.','The search lab uses local fixtures. Live catalog failures use separate error pages.'],
    [['Søk qqq: se originaltekst og knappen for nytt søk.','Search qqq: see the original query and clear-search control.'],['Søk termokop: velg retting og finn kopper.','Search termokop: choose the correction and find mugs.'],['Søk retur i produktområdet: utvid området uten å skrive på nytt.','Search retur in product scope: widen it without retyping.']],['search-typos','search-scope']),
  a('filter-multi-select','find-products','multi','fashion',
    ['Filtre: OR innen en egenskap, AND mellom egenskaper','Filters: OR within an attribute, AND across attributes'],
    ['Brun eller svart kan være to akseptable farger. Størrelse L og lagerstatus skal likevel gjelde den samme varianten.','Brown or black can both be acceptable colors. Size L and stock status must still apply to the same variant.'],
    ['Radio-knapper for farge hindrer sammenligning; AND mellom fargene gjør en enkel variant umulig.','Color radios prevent comparison; AND between colors makes a single variant impossible.'],
    ['Bruk flere valg for alternative verdier. Forklar logikken i tekniske filtre der kunden kan forvente noe annet.','Use multiple selection for alternative values. Explain technical filters where shoppers may expect different logic.'],
    ['ReAI leverer varianter og egenskaper. Den delte filtermodellen matcher alle kriterier per variant.','ReAI supplies variants and attributes. The shared filter model matches all criteria per variant.'],
    ['Famme tester lager med en merket fixture; Index bruker publiserte backend-data.','Famme tests stock using labeled fixtures; Index uses published backend data.'],
    [['Velg brun og svart: vis unionen av fargene.','Select brown and black: show the union of those colors.'],['Velg L og på lager: ingen vare skal passe gjennom to forskjellige varianter.','Select L and in stock: no item may match through different variants.'],['Fjern én farge: behold størrelse og den andre fargen.','Remove one color: retain size and the remaining color.']],['filters','filter-counts']),
  a('applied-filter-overview','find-products','chips','fashion',
    ['Valgte filtre: oversikt og fjerning av ett valg','Applied filters: overview and individual removal'],
    ['Vis aktive begrensninger over resultatlisten med lesbare navn. Kunden skal kunne fjerne ett valg uten å nullstille alt.','Show active constraints above results with readable labels. Let shoppers remove one choice without resetting everything.'],
    ['En knapp med tallet 3 forteller ikke hvilke tre valg som skjuler varer.','A button labeled 3 does not explain which choices are hiding products.'],
    ['Bruk filterbrikker for oversikten og behold hele filterpanelet for endringer. Inkluder også valg fra lenker.','Use chips for the overview and retain the full panel for edits. Include constraints arriving through links.'],
    ['Filternavn og verdier kommer fra samlingens publiserte data, ikke en fast liste med irrelevante egenskaper.','Facet names and values come from the collection data, not a fixed list of irrelevant attributes.'],
    ['Delte filterkontroller brukes også i de ekte katalogdesignene.','Shared filter controls also serve the live catalog designs.'],
    [['Velg størrelse og farge; se begge som lesbare brikker.','Select size and color; see both as readable chips.'],['Fjern fargebrikken og behold størrelsen.','Remove the color chip and retain size.'],['På mobil: avbryt et utkast; aktive brikker skal være uendret.','On mobile, cancel a draft; active chips must remain unchanged.']],['mobile-filters','filter-multi-select']),
  a('filter-counts','find-products','multi','fashion',
    ['Filterantall og nulltreff uten å fjerne kundens valg','Filter counts and zero matches without losing choices'],
    ['Antallet ved et filter skal forklare hva valget kan gi i nåværende kontekst. Behold allerede valgte nullverdier som mulige å fjerne.','A facet count should describe its effect in the current context. Keep selected zero-count values removable.'],
    ['Et statisk antall fra hele butikken kan love treff som ikke finnes i samlingen.','A storewide static count can promise matches absent from the collection.'],
    ['Beregn antall med de andre filtrene aktive. Forklar antall produkter kontra antall varianter.','Calculate counts with other facets active. Distinguish product counts from variant counts.'],
    ['Filtermodellen teller produkter med en variant som oppfyller kriteriene, og ignorerer egen facet ved antallsberegning.','The filter model counts products with a qualifying variant and omits the current facet from its count calculation.'],
    ['Antallet er ikke et løfte om tilgjengelighet ved senere betaling.','Counts are not a promise of availability at later payment.'],
    [['Velg L og på lager: brun Softy skal ha null treff.','Choose L and in stock: brown Softy should have zero matches.'],['Fjern lagerkravet og kontroller at restordre kan komme tilbake.','Remove the stock requirement and check backorders can return.'],['Behold en valgt nullverdi og fjern den fra oversikten.','Keep a selected zero value and remove it from the overview.']],['filter-multi-select','stock']),
  a('load-more-return','find-products','pages','fashion',
    ['Mer lasting og tilbake til samme produktliste','Incremental loading and returning to the product list'],
    ['Behold valgt filter, sortering og plass når kunden går tilbake fra et produkt. Ekstra lasting må ha en forståelig slutt.','Preserve filters, sorting and position when returning from a product. Incremental loading needs a recognizable end.'],
    ['En tilbaketur til toppen tvinger kunden til å finne igjen det de nettopp vurderte.','Returning to the top makes shoppers relocate what they just evaluated.'],
    ['Små samlinger trenger ingen last mer-knapp. Større kataloger trenger gjenoppretting av både lastede sider og posisjon.','Small collections need no load-more control. Larger catalogs must restore loaded pages as well as position.'],
    ['Den delte listekonteksten knytter returnavigasjon til samme produkt-URL, filtre og sortering.','Shared list context associates return navigation with product URL, filters and sorting.'],
    ['Her er små lister; en fler-siders lastestrategi er veiledning, ikke en demonstrert backend-funksjon.','These lists are small; a multi-page loading strategy is guidance, not a demonstrated backend feature.'],
    [['Filtrer, åpne et produkt og bruk Tilbake til listen.','Filter, open a product and use Back to the list.'],['Kontroller at valgt variant og filterbrikker følger konteksten.','Check that the selected variant and filter chips retain context.'],['Med en stor katalog: test om den sist lastede siden gjenopprettes.','For a large catalog, test restoration of the last loaded page.']],['breadcrumbs','pagination-seo']),

  a('variant-images','choose-products','thumbnails','fashionProduct',
    ['Variantbilder som følger valgt farge','Variant images follow the selected color'],
    ['Hovedbildet og variantnavnet skal vise samme valg. Et fargebytte må ikke stille kunden foran et gammelt bilde.','The main image and variant name should reflect the same selection. A color change must not leave the old image visible.'],
    ['Svart i radiovalget og brun i bildet skaper usikkerhet om hva som bestilles.','Black selected alongside a brown photograph creates uncertainty about the order.'],
    ['Bruk eksplisitt kobling mellom variant og bilde. Manglende bilder skal forklares, ikke erstattes med feil farge.','Map variants to images explicitly. Explain missing images rather than substituting the wrong color.'],
    ['Site API har bilder og varianter. Fixture-koblingen er separat og brukes ikke i ekte checkout.','Site API supplies images and variants. Fixture mappings remain separate from live checkout.'],
    ['Bildezoom inspiserer bildet; den velger ikke en annen størrelse eller farge.','Image zoom inspects the image; it does not select a different size or color.'],
    [['Bytt brun til svart og kontroller bilde og tekst.','Switch brown to black and check image and text.'],['Åpne zoom og lukk med Escape: variantvalget beholdes.','Open zoom and close with Escape: retain the variant choice.'],['Åpne fra filtrert liste: start med den matchede fargen.','Open from filtered results: start with the matching color.']],['variants','image-zoom-mobile']),
  a('variant-names','choose-products','lists','fashionProduct',
    ['Fargenavn og størrelser som tekst, ikke bare symboler','Color and size names as text, not just symbols'],
    ['Vis et lesbart navn ved farge og størrelse. Fargeprøven er et tillegg til teksten, ikke en erstatning.','Provide readable color and size names. A swatch supplements the text rather than replacing it.'],
    ['To nesten like farger er vanskelige å skille; en skjermleser kan ikke bruke fargetonen som navn.','Similar colors are hard to distinguish; a screen reader cannot use hue as a label.'],
    ['Unike navn og tilstandsmarkering hjelper alle. For tekniske varianter bør enheten inngå i navnet.','Unique names and selection states help everyone. Technical variants should include their units.'],
    ['Bruk publiserte variantverdier. Ikke utled svart fra et filnavn i en ekte katalog.','Use published variant values. Never infer black from a filename in a live catalog.'],
    ['Famme-fixturen har eksplisitte oversatte navn og native radiovalg.','The Famme fixture has explicit translated names and native radio choices.'],
    [['Bruk tastatur til fargevalg og kontroller lesbart valgt navn.','Use the keyboard to select a color and check its readable name.'],['Bytt språk: samme variant skal beholdes.','Switch language: retain the same variant.'],['Kontroller utsolgt-tekst uten å stole på gråfargen alene.','Check sold-out text without relying on gray styling alone.']],['touch-targets','variants']),
  a('size-unavailable','choose-products','lists','fashionProduct',
    ['Utsolgte størrelser: forklar valget og neste mulighet','Unavailable sizes: explain status and alternatives'],
    ['Behold utsolgte størrelser synlige og forklar hvorfor de ikke kan velges. Restordre trenger egen tekst.','Keep unavailable sizes visible and explain why they cannot be selected. Backorders need separate wording.'],
    ['Hvis L forsvinner etter fargebytte, kan kunden tro at størrelsen aldri selges.','If L disappears after a color change, shoppers may think it is never sold.'],
    ['Vis statuser per farge/størrelse. Lagervarsel tilbys bare når en fungerende varseltjeneste er konfigurert.','Show status for each color/size pair. Offer stock alerts only when a working notification service is configured.'],
    ['Site API availability og tenantens lagerpolicy bestemmer kjøpbarhet. Et UI-valg kan ikke overstyre serveren.','Site API availability and merchant stock policy determine purchasability. UI selection cannot override the server.'],
    ['Fixturen har utsolgt og restordre; den sender ingen lager-e-post.','The fixture includes sold-out and backorder states; it sends no stock emails.'],
    [['Velg brun Softy: L skal vises som utsolgt.','Choose brown Softy: L should remain visible as sold out.'],['Velg svart XL: se restordre, ikke på lager.','Choose black XL: see backorder rather than in stock.'],['Bytt til en farge som ikke har valgt størrelse: be om nytt valg.','Switch to a color lacking the chosen size: request a new selection.']],['stock','variants']),
  a('image-scale','choose-products','scale','product',
    ['Produktbilder som forklarer størrelse og skala','Product images that explain size and scale'],
    ['Suppler bilder med mål og en kjent referanse når størrelsen påvirker valget. Et pent utsnitt gir ikke automatisk skala.','Supplement images with dimensions and a known reference when size affects choice. An attractive crop does not establish scale.'],
    ['En 350 ml og 500 ml kopp kan se like store ut hvis begge fyller bildeflaten.','A 350 ml and 500 ml mug can look identical when both fill their image frames.'],
    ['Bruk dokumenterte mål og riktig enhet. Mål på kroppen og mål på plagget er forskjellige opplysninger.','Use documented dimensions and correct units. Body measurements and garment measurements are different information.'],
    ['Publiser faktiske egenskaper i ReAI og vedlikehold fotografier med riktig referanse på nettstedet.','Publish factual attributes in ReAI and maintain correctly scaled photography on the site.'],
    ['Kopplaben viser volum som tekst. Den har ingen fotografi som dokumenterer fysisk skala.','The mug lab shows volume as text. It has no photograph proving physical scale.'],
    [['Sammenlign begge kopper og finn volum uten å tolke illustrasjonen.','Compare both mugs and find capacity without interpreting the illustration.'],['På en ekte vare: kontroller at mål gjelder produktet, ikke emballasjen.','On a real item, verify dimensions describe the product rather than packaging.'],['La en deltaker forklare forventet størrelse før bestilling.','Ask a participant to explain the expected size before ordering.']],['product-details','spec-units']),
  a('image-zoom-mobile','choose-products','zoom','fashionProduct',
    ['Mobil bildezoom med tydelig lukking og fokus','Mobile image zoom with clear closing and focus'],
    ['La kunden inspisere detaljer i et større bilde uten å miste produktvalget. Tilby en synlig lukkeknapp og tastaturvei.','Let shoppers inspect a larger image without losing selection. Provide visible closing controls and keyboard access.'],
    ['Å forstørre en liten fil gir bare flere piksler. En fullskjermvisning uten utgang kan fange kunden.','Enlarging a tiny file only creates pixels. A full-screen view without an exit can trap shoppers.'],
    ['Vis tilpasning til skjerm og en eksplisitt detaljvisning. Behold miniatyrer slik at kunden kjenner bildene.','Offer fit-to-screen and an explicit detail view. Retain thumbnails so shoppers recognize images.'],
    ['Nettsiden eier zoomdialogen. Bilder må ha tilstrekkelig kildeoppløsning; AVIF alene garanterer ikke detaljnivå.','The site owns the zoom dialog. Source images need sufficient resolution; AVIF alone guarantees no detail.'],
    ['Famme og Lookbook bruker autoriserte AVIF-bilder; zoom endrer ingen produktdata.','Famme and Lookbook use authorized AVIF images; zoom changes no product data.'],
    [['Åpne Forstørr bilde ved 390 px og prøv detaljvisning.','Open Enlarge image at 390 px and try detail view.'],['Velg en miniatyr: telleren og bildet skal følge valget.','Choose a thumbnail: image and counter should follow selection.'],['Lukk med Escape og kontroller fokus på åpneren.','Close with Escape and check focus returns to the opener.']],['keyboard-dialogs','variant-images']),
  a('price-range','choose-products','lists','product',
    ['Fra-pris og prisområde for varianter','From-prices and variant price ranges'],
    ['Vis hva en fra-pris betyr og oppdater til valgt variants pris. Ikke la en billig, irrelevant variant stå som kjøpets pris.','Explain from-prices and update to the selected variant price. Do not present an irrelevant cheap variant as the purchase price.'],
    ['Et gavekort på 1000 kr skal ikke beholde prisetiketten fra et 100 kr-alternativ.','A 1000 kr gift card must not retain the price label from a 100 kr option.'],
    ['Bruk område når flere sammenlignbare varianter har ulik pris. Skill pakkepris, enhetspris og rabatt.','Use ranges for comparable variants with different prices. Separate pack, unit and discounted prices.'],
    ['ReAI sine variantpriser er kilden; checkout beregner den endelige totalen på serveren.','ReAI variant prices are the source; checkout calculates the final total server-side.'],
    ['Kopplaben viser faste priser for to produkter. Ekte gavekort demonstrerer beløpsvarianter.','The mug lab shows fixed prices for two products. Live gift cards demonstrate amount variants.'],
    [['Åpne gavekortets variantvalg uten å starte checkout.','Open gift-card amount selection without starting checkout.'],['Velg nytt beløp: synlig pris skal endres sammen med varianten.','Choose a different amount: update visible price with the variant.'],['Kontroller prisbeskrivelsen i produktlisten mot den valgte varen.','Compare listing price wording with the selected item.']],['unit-pricing','variants']),
  a('product-video','choose-products','scale','fashionProduct',
    ['Produktvideo som tillegg til fakta og bilder','Product video supplements facts and images'],
    ['Bruk video til å vise bevegelse eller bruk. Viktig informasjon må også finnes som tekst og stillbilder.','Use video to show movement or use. Essential information must also exist as text and still images.'],
    ['En kunde på tregt nett eller uten lyd kan ikke være avhengig av å se hele filmen.','Shoppers on slow connections or without audio cannot depend on watching a full video.'],
    ['Video bør startes av kunden, ha kontroller og relevant teksting. Unngå automatisk lyd og bakgrunnsvideo som dekker valgene.','Use shopper-initiated video with controls and relevant captions. Avoid automatic audio and background video obscuring choices.'],
    ['Innhold og medielevering er nettstedets ansvar. Dokumenter fil, språk og rettigheter før publisering.','Content and media delivery belong to the site. Document files, languages and rights before publication.'],
    ['Denne fixturen har bilder, ikke produktvideo. Artikkelen forklarer et mulig tillegg.','This fixture has images, not product video. The article describes a possible extension.'],
    [['Finn produktfakta uten video eller lyd.','Find product facts without video or audio.'],['Ved video i egen butikk: test pause, teksting og tastatur.','For your store video, test pause, captions and keyboard use.'],['Kontroller at video ikke forsinker produktvalgene på mobil.','Check video does not delay product choices on mobile.']],['performance','reduced-motion']),
  a('spec-units','choose-products','compare','comparison',
    ['Spesifikasjoner med enheter og ukjent-verdi','Specifications with units and unknown values'],
    ['Vis tall sammen med enheten og forklar ukjent informasjon. Null betyr ikke det samme som manglende data.','Show numbers with units and explain unknown information. Zero is not the same as missing data.'],
    ['En vekt på 0 kg kan se fantastisk ut, men er feil hvis leverandøren ikke oppga vekten.','A weight of 0 kg may look excellent but is wrong when the supplier omitted it.'],
    ['Normaliser sammenlignbare enheter før sortering. Behold presisjon som er relevant for kjøpsoppgaven.','Normalize comparable units before sorting. Retain precision relevant to the shopping task.'],
    ['Produktets publiserte egenskaper må ha enhet og pålitelig kilde. Nettstedet formaterer tall for språk.','Published attributes need units and trustworthy sources. The site formats numbers for the locale.'],
    ['Kvern Pro har bevisst ukjent vekt i den fiktive sammenligningen.','Kvern Pro deliberately has unknown weight in the fictional comparison.'],
    [['Sammenlign Mini og Pro: vekt skal vises som ukjent for Pro.','Compare Mini and Pro: show Pro weight as unknown.'],['Kontroller W, g, kg og V ved riktige rader.','Check W, g, kg and V beside the correct rows.'],['Bytt språk: tallformat endres uten å endre egenskapene.','Switch language: format numbers without changing specifications.']],['comparison-differences','unit-pricing']),
  a('comparison-differences','choose-products','compare','comparison',
    ['Sammenligning: fremhev forskjeller uten å skjule pris','Comparison: show differences while retaining price'],
    ['La kunden skjule like egenskaper, men behold produktnavn, pris og forklaring på ukjente verdier.','Let shoppers hide identical attributes while keeping product names, prices and unknown-value explanations.'],
    ['En lang tabell med mange like rader kan skjule de to forskjellene som avgjør kjøpet.','A long table of identical rows can conceal the two differences that decide the purchase.'],
    ['Bruk sammenligning ved tekniske valg. Visuelle produkter kan ha mer nytte av bilder og passform enn en stor tabell.','Use comparison for technical choices. Visual products may benefit more from photography and fit than a large table.'],
    ['Sammenlign publiserte egenskaper med samme definisjon; aldri fyll mangler med gjettede nuller.','Compare published attributes sharing the same definition; never fill gaps with guessed zeros.'],
    ['Laben sammenligner opptil tre fiktive kverner og har en bare forskjeller-kontroll.','The lab compares up to three fictional grinders and has a differences-only control.'],
    [['Velg to kverner og slå på bare forskjeller.','Select two grinders and enable differences only.'],['Spenning 230 V skal skjules; pris skal beholdes.','Hide identical 230 V voltage while retaining price.'],['Fjern én kvern: ikke vis en sammenligning med bare ett produkt.','Remove one grinder: do not show a one-product comparison.']],['comparison','spec-units']),
  a('sticky-purchase-mobile','choose-products','lists','fashionProduct',
    ['Fast kjøpsknapp på mobil: behold variant og pris','Sticky mobile purchase controls retain variant and price'],
    ['En fast kjøpsknapp må ha samme tilstand som produktvalget og ikke dekke informasjon eller fokus.','A sticky purchase control must share product-selection state without covering information or focus.'],
    ['En ekstra aktiv knapp kan tillate kjøp selv om den ordinære knappen krever størrelse.','An additional active button may allow purchase while the main button requires size selection.'],
    ['Bruk først en tydelig ordinær knapp. Legg til fast kontroll bare når lange produktsider gir dokumentert behov.','Start with a clear standard control. Add a sticky control only when long product pages justify it.'],
    ['Begge kontroller må lese samme variant- og lagerstatus. Serveren validerer alltid kjøpet.','Both controls must read the same variant and availability state. The server always validates the purchase.'],
    ['Eksemplet bruker ordinær knapp. Det demonstrerer ikke en ekstra fast kjøpslinje.','This example uses the standard control. It demonstrates no additional sticky purchase bar.'],
    [['På mobil: finn kjøpsvalget og kontroller størrelsekravet.','On mobile, locate purchase choices and check the size requirement.'],['Ved en fast kontroll i egen butikk: test utsolgt og manglende størrelse.','For a sticky control in your store, test unavailable and missing sizes.'],['Zoom siden: ingen fast kontroll må dekke fokus eller vilkår.','Zoom the page: no fixed control may cover focus or policies.']],['variants','touch-targets']),

  a('drawer-checkout','cart-checkout','dialog','fashionProduct',
    ['Kurv i skuff: redigering, sum og en tydelig utgang','Cart drawers: editing, totals and a clear exit'],
    ['En skuff bør vise hva som ble lagt til og la kunden fortsette, redigere eller lukke. Ikke gjør den til en blindvei.','A drawer should confirm the added item and allow continuation, editing or closing. Do not make it a dead end.'],
    ['En fullskjerms skuff på mobil kan skjule både produktet og hvordan man kommer tilbake.','A full-screen mobile drawer can hide both the product and the route back.'],
    ['Bruk native dialog, synlig lukkeknapp og tydelig tomtilstand. Ekte checkout skal bare tilbys for reelle kjøpbare varer.','Use a native dialog, visible close control and clear empty state. Offer live checkout only for real purchasable items.'],
    ['Ekte varer valideres av ReAI checkout. Famme-kurven har egen nøkkel og sender ingen ordre.','Real items are validated by ReAI checkout. The Famme cart has its own key and submits no orders.'],
    ['Testskuffen har variantredigering, antall og angre, uten betalingsknapp.','The fixture drawer offers variant editing, quantities and undo without payment controls.'],
    [['Legg en variant i testkurven: se valgt farge, størrelse og sum.','Add a fixture variant: see color, size and total.'],['Lukk med Escape og fortsett produktvalget.','Close with Escape and continue selecting products.'],['Fjern siste vare: se tomtilstand, ikke en gammel total.','Remove the last item: show empty state rather than an old total.']],['cart','cart-edit-variants','keyboard-dialogs']),
  a('cart-edit-variants','cart-checkout','cart','fashionProduct',
    ['Endre størrelse eller farge direkte fra kurven','Edit cart size or color without starting over'],
    ['La kunden korrigere en variant uten å fjerne varen og finne produktet på nytt. Behold antallet ved endringen.','Let shoppers correct a variant without removing the item and finding it again. Preserve quantity when editing.'],
    ['Fjerning og ny innlegging kan miste antall og gjøre en enkel retting til flere oppgaver.','Removing and adding again can lose quantity and turn a small correction into several tasks.'],
    ['Bruk de samme tilgjengelighetsreglene som på produktet. Et avbrutt redigeringsvalg skal ikke endre kurven.','Use the same availability rules as the product page. Canceled edits must not change the cart.'],
    ['Identitet er produkt pluss variant, ikke bare tittelen. Sammenfallende varianter kan slås sammen innen antallsgrensen.','Identity is product plus variant, not just title. Matching variants may merge within the quantity limit.'],
    ['Redigeringen gjelder bare den separate fashion-fixturen, ikke en betalingsordre.','Editing applies only to the separate fashion fixture, not a payment order.'],
    [['Legg inn to av samme størrelse; endre til en annen tilgjengelig størrelse.','Add quantity two; edit to another available size.'],['Lukk redigeringen uten å lagre: behold den gamle varianten.','Close editing without saving: retain the old variant.'],['Velg en eksisterende variant: slå sammen antall uten duplikatlinje.','Choose an existing variant: merge quantities without a duplicate line.']],['variants','drawer-checkout']),
  a('cart-stock-recheck','cart-checkout','lists','fashionProduct',
    ['Kontroller lager på nytt før checkout','Recheck availability before checkout'],
    ['En lagret kurv er et ønske, ikke en lagerreservasjon. Forklar endret kjøpbarhet før kunden kan betale.','A saved cart is an intention, not a stock reservation. Explain changed purchasability before payment.'],
    ['En gammel lokal kurv kan inneholde en variant som nå er utsolgt eller har ny pris.','An old local cart can contain a now-unavailable variant or a changed price.'],
    ['Behold varen synlig med forklaring og rediger/fjern-valg. Ikke slett stille eller erstatt størrelse automatisk.','Keep the item visible with explanation and edit/remove actions. Never silently delete or replace sizes.'],
    ['ReAI checkout er autoritativt for pris og kjøpbarhet; lesedata gir tidligere hjelp i nettstedet.','ReAI checkout is authoritative for price and purchasability; delivery reads provide earlier guidance.'],
    ['Fixturen viser utilgjengelige lagrede varianter og tilbyr redigering. Den reserverer aldri lager.','The fixture flags saved unavailable variants and offers editing. It never reserves stock.'],
    [['Kontroller at utsolgt ikke blir presentert som på lager i kurven.','Check unavailable stock is not presented as in stock in the cart.'],['Endre en utilgjengelig variant til en tilgjengelig variant.','Edit an unavailable variant to an available one.'],['I ekte butikk: test serveravvisning uten å tømme hele kurven.','In a real store, test server rejection without clearing the entire cart.']],['stock','errors']),
  a('free-shipping-threshold','cart-checkout','threshold','checkout',
    ['Fri frakt: forklar grense og unntak ved valget','Free shipping: explain thresholds and exceptions'],
    ['Vis både betingelsen og aktuell frakt. Et banner med fri frakt er utilstrekkelig hvis kjøpet ikke kvalifiserer.','Show both the condition and current shipping charge. A free-shipping banner is insufficient when the order is ineligible.'],
    ['Et terskelbudskap kan presse kunden til tillegg som koster mer enn frakten de sparer.','A threshold prompt can push shoppers toward extras costing more than the shipping they save.'],
    ['Beregn etter riktige rabatter og unntak. Gjør videre kjøp frivillig, og vis det normale leveringsvalget.','Calculate using correct discounts and exclusions. Keep additional purchasing optional and show normal delivery choices.'],
    ['Fraktregler og checkout-total kommer fra backend. Ikke lov gratis fysisk frakt for et digitalt gavekort.','Shipping rules and checkout totals come from the backend. Never promise free physical shipping for a digital gift card.'],
    ['Checkout-laben har fast 49 kr eller gratis henting, ingen fri-frakt-terskel.','The checkout lab has fixed 49 kr shipping or free pickup, not a free-shipping threshold.'],
    [['Velg sending og henting: totalsammenhengen skal være tydelig.','Choose shipping and pickup: totals should clearly correspond.'],['Ved terskel i egen butikk: test beløpet rett under og over grensen.','For your store threshold, test amounts just below and above it.'],['Bruk rabatt: kontroller om fraktgrensen beregnes før eller etter rabatt.','Apply a discount: verify whether the threshold uses the discounted amount.']],['costs','promotions']),
  a('shipping-estimate-early','cart-checkout','shipping','checkout',
    ['Fraktestimat før kunden fyller hele checkout','Shipping estimates before completing checkout'],
    ['Gi tidlig informasjon om leveringspris og hva som kreves for et presist tilbud. Ukjent frakt skal ikke se gratis ut.','Provide early delivery-cost information and explain what a precise quote needs. Unknown shipping must not look free.'],
    ['En lav produktpris kan bli irrelevant når frakt først avsløres etter mange felt.','A low product price can become irrelevant when shipping appears after many fields.'],
    ['En fast pris kan vises direkte. Destinasjonsavhengig frakt bør merkes som estimat til tilbudet er bekreftet.','Show fixed prices directly. Destination-dependent shipping should remain labeled an estimate until a quote is confirmed.'],
    ['Tilgjengelige tjenester avhenger av selger, adresse og pakke. Hosted checkout eier det bindende fraktvalget.','Available services depend on merchant, address and parcel. Hosted checkout owns the binding shipping selection.'],
    ['Laben har merkede simulerte priser og datoer. Den henter ingen transportørtilbud.','The lab uses labeled simulated prices and dates. It requests no carrier quotes.'],
    [['Finn fraktprisen før du går til gjennomgang.','Find the shipping price before continuing to review.'],['Bytt til henting: se både nytt beløp og hentested.','Switch to pickup: see the new cost and pickup location.'],['I ekte frakt: test manglende tilbud uten å vise null som pris.','For live shipping, test missing quotes without displaying zero cost.']],['delivery','costs']),
  a('coupon-errors','cart-checkout','form','product',
    ['Rabattfeil med forklaring og beholdt kurv','Coupon errors with explanations and preserved baskets'],
    ['Forklar om koden er ukjent, utløpt eller ikke gjelder varene. Behold kurv og inntastet kode så kunden kan rette.','Explain whether a code is unknown, expired or ineligible. Preserve the basket and typed code for correction.'],
    ['Ugyldig alene forteller ikke om kunden skrev feil eller gavekortet er unntatt.','Invalid alone does not distinguish a typo from an excluded gift card.'],
    ['Gi bare forklaringer serveren kan bekrefte. Ikke avslør private kampanjer eller interne begrensninger.','Provide only explanations the server can confirm. Do not disclose private campaigns or internal restrictions.'],
    ['ReAI validerer ekte rabatter. Klientens visning skal bruke serverens resultat og oppdatert total.','ReAI validates real discounts. Client displays should use the server result and updated total.'],
    ['LAB10 er bare en kopprabatt i minnet; gavekort og donasjoner omfattes aldri.','LAB10 is only an in-memory mug discount; it never applies to gift cards or donations.'],
    [['Bruk WRONG: se konkret feil og behold alle kurvlinjer.','Use WRONG: see a specific error and retain all basket lines.'],['Bytt til LAB10: se rabatt bare på kopper.','Change to LAB10: discount only mugs.'],['Fjern koden: totalen skal gå tilbake uten å fjerne varer.','Remove the code: restore the total without removing items.']],['promotions','errors']),
  a('guest-email','cart-checkout','optional','checkout',
    ['E-post i gjestecheckout uten påtvunget konto','Guest checkout email without mandatory registration'],
    ['Forklar e-post som kontakt for kjøpet. Nyhetsbrev og kontooppretting er separate valg.','Explain email as purchase contact information. Newsletter signup and account creation are separate choices.'],
    ['Et kontaktfelt skal ikke gjøre kunden abonnent eller kreve et passord.','A contact field must not subscribe the shopper or require a password.'],
    ['Bruk type email og autocomplete email. Behold e-posten når kunden retter adresse eller leveringsvalg.','Use type email and autocomplete email. Retain email when correcting an address or changing fulfillment.'],
    ['Checkout-kontakt og newsletter:subscribe er forskjellige API-operasjoner med forskjellige formål.','Checkout contact and newsletter:subscribe are separate API operations serving different purposes.'],
    ['Laben sender ingen e-post og oppretter ingen konto.','The lab sends no email and creates no account.'],
    [['Finn e-post uten passordfelt.','Find email without a password field.'],['Rett en ugyldig e-post uten å miste navnet.','Correct an invalid email without losing the name.'],['Kontroller at betaling ikke forhåndsvelger markedsføring.','Check payment never preselects marketing consent.']],['guest-checkout','consent-preferences']),
  a('checkout-autofill','cart-checkout','optional','checkout',
    ['Autofyll og riktig tastatur i checkout','Autofill and appropriate checkout keyboards'],
    ['Bruk standard feltsemantikk så nettleseren kan hjelpe med navn, e-post og adresse. Ikke lag egendefinerte felter uten behov.','Use standard field semantics so browsers can assist with name, email and address. Avoid unnecessary custom inputs.'],
    ['Et talltastatur kan hjelpe postnummer, men type number kan fjerne ledende nuller.','A numeric keyboard helps postal entry, but type number can discard leading zeros.'],
    ['Postnummer er tekst med inputmode numeric i dette norske eksemplet. Andre markeder kan ha bokstaver.','Postal codes are text with numeric inputmode in this Norwegian example. Other markets may use letters.'],
    ['Nettsiden eier autocomplete og feltoppsett; backend validerer adresser etter aktuelt marked.','The site owns autocomplete and field layout; the backend validates addresses for the relevant market.'],
    ['Laben viser semantikken. Faktisk autofyll varierer mellom nettlesere og lagrede profiler.','The lab shows semantics. Actual autofill varies by browser and saved profiles.'],
    [['Kontroller name, email, street-address og postal-code på feltene.','Check name, email, street-address and postal-code on fields.'],['Skriv 0001: behold alle fire sifre.','Enter 0001: retain all four digits.'],['Test eget autofyll og korriger ett felt uten å nullstille andre.','Test your autofill and correct one field without resetting others.']],['required-fields','accessible-forms']),
  a('address-validation','cart-checkout','address','checkout',
    ['Adressekontroll: skill format fra leverbar adresse','Address checks: distinguish format from deliverability'],
    ['Et gyldig postnummerformat beviser ikke at adressen finnes. Vis forslag fra en reell adressekilde som forslag, ikke stille retting.','Valid postal formatting does not prove an address exists. Show real-source suggestions as choices rather than silent corrections.'],
    ['Automatisk erstatning kan fjerne en ny adresse som ennå ikke finnes i registeret.','Automatic replacement can remove a new address not yet present in a registry.'],
    ['Behold original og foreslått adresse ved siden av hverandre når retting trengs. Avklar hvordan ukjente adresser håndteres.','Show original and suggested addresses together when correction is needed. Define handling for unknown addresses.'],
    ['Formatkontroll, adresseregister og transportørtilbud er tre forskjellige kontroller. Integrasjonen må beskrive hvilken den bruker.','Format validation, address registry lookup and carrier quotes are three different checks. Document which the integration uses.'],
    ['Laben sjekker bare norsk feltformat. Den bekrefter aldri at Testgata finnes.','The lab checks Norwegian field formats only. It never verifies that Testgata exists.'],
    [['Bruk 123: få formatfeil på postnummeret.','Use 123: receive a postal format error.'],['Bruk 0001: format kan godtas uten en påstand om leverbarhet.','Use 0001: accept formatting without claiming deliverability.'],['I egen integrasjon: test en ukjent adresse med beholdt original.','In your integration, test an unknown address while retaining the original.']],['delivery','checkout-autofill']),
  a('optional-fields','cart-checkout','optional','checkout',
    ['Valgfrie felt og hvorfor påkrevde felt trengs','Optional fields and reasons for required information'],
    ['Merk både påkrevd og valgfritt. Vis ekstra felt når kjøpet trenger dem, og forklar hvorfor data samles inn.','Label both required and optional fields. Reveal additional fields when the purchase needs them and explain collection purposes.'],
    ['Ekstra adresse og organisasjonsnummer kan se obligatoriske ut selv for en vanlig privatkunde.','Address line two and organization number can look mandatory even for a private shopper.'],
    ['Bedriftsvalg kan vise organisasjonsnummer; henting kan fjerne leveringsadressekrav. Behold eksisterende tekst ved bytte.','Business selection can reveal an organization number; pickup can remove shipping-address requirements. Retain text when switching.'],
    ['Tenant og leveringsvalg avgjør reelle krav. Ikke fjern informasjon transportøren faktisk krever.','Merchant and fulfillment determine actual requirements. Never remove information genuinely required by the carrier.'],
    ['Laben simulerer krav og sender ingen personinformasjon.','The lab simulates requirements and transmits no personal information.'],
    [['Velg henting: tom gateadresse skal ikke stoppe gjennomgang.','Choose pickup: a blank street address should not block review.'],['Velg bedrift: vis og valider organisasjonsnummer.','Choose business: show and validate organization number.'],['Åpne valgfri ekstra adresse og la den være tom.','Open optional address line two and leave it empty.']],['required-fields','guest-email']),
  a('payment-failure-retry','cart-checkout','form','checkout',
    ['Betalingsfeil: trygg retry uten dobbeltordre','Payment failures: safe retry without duplicate orders'],
    ['Skill bekreftet feil fra ukjent eller avventende status. En timeout betyr ikke at betalingen mislyktes.','Distinguish confirmed failure from unknown or pending status. A timeout does not mean payment failed.'],
    ['Et raskt nytt betalingsforsøk etter avbrutt svar kan skape to belastninger hvis første forsøk lyktes.','A quick retry after a lost response can create two charges if the first attempt succeeded.'],
    ['Vis neste steg ut fra bekreftet status og behold checkout-kontekst. Ikke opprett en ny ordre bare ved omlasting.','Show next steps based on confirmed status and retain checkout context. Never create a new order merely on reload.'],
    ['Backend må eie status, idempotens og avstemming mot Adyen. Nettstedets retur-URL beviser ingenting om betaling.','The backend must own status, idempotency and Adyen reconciliation. A site return URL proves nothing about payment.'],
    ['Laben demonstrerer feil, avventer og betalt som separate simulerte utfall.','The lab demonstrates failure, pending and paid as separate simulated outcomes.'],
    [['Velg mislyktes: behold gjennomgang og kontaktinfo.','Choose failure: retain review and contact details.'],['Velg avventer: be om statuskontroll fremfor blind retry.','Choose pending: request a status check instead of blind retry.'],['Velg betalt: bekreftelsesoverskriften skal være tydelig simulert.','Choose paid: the confirmation heading must clearly say simulated.']],['payment','errors']),
  a('order-review','cart-checkout','confirm','checkout',
    ['Gjennomgang med varer, levering og riktig total','Order review with items, fulfillment and correct totals'],
    ['Vis valgt vare, antall, levering og total før siste handling. Endre-valget skal beholde det kunden allerede fylte inn.','Show item, quantity, fulfillment and total before the final action. Editing should preserve completed information.'],
    ['En samlet sum uten fraktlinje forklarer ikke hvorfor den er høyere enn produktprisen.','A total without a shipping line does not explain why it exceeds product price.'],
    ['Hold gjennomgangen kort og lesbar. B2B faktura må vises som kredittordre, ikke kortbetaling.','Keep review concise and readable. B2B invoicing must appear as a credit order rather than card payment.'],
    ['Serverberegnet total og valgt frakt er autoritativt i ReAI checkout. Labens total gjelder bare simuleringen.','Server-calculated totals and shipping are authoritative in ReAI checkout. Lab totals apply only to simulation.'],
    ['Laben har redigering og et detaljert sammendrag uten å belaste noe.','The lab offers editing and a detailed summary without charging anything.'],
    [['Velg tre varer og sending: vis 300 + 49 = 349 kr.','Choose three items and shipping: show 300 + 49 = 349 kr.'],['Gå tilbake og velg henting: vis total 300 kr.','Go back and choose pickup: show total 300 kr.'],['Kontroller at ekstra adresselinje følger gjennomgangen.','Check the optional address line appears in review.']],['confirmation-summary','costs']),

  a('confirmation-summary','after-purchase','confirm','checkout',
    ['Bekreftelse: status først, så ordre og neste steg','Confirmation: status first, then order and next steps'],
    ['Bekreft det som faktisk er kjent: ordre, betalingsstatus, vare, frakt og total. Tilleggstilbud kommer etter den informasjonen.','Confirm what is actually known: order, payment state, items, shipping and total. Additional offers come after that information.'],
    ['Takk alene gjør kunden usikker på om betalingen er bekreftet og om e-post kommer.','Thanks alone leaves shoppers unsure whether payment is confirmed and email will follow.'],
    ['Bruk ulike tekster for betalt, avventer og faktura. Fortell hva kunden bør gjøre nå og hvor hjelp finnes.','Use distinct copy for paid, pending and invoice. Explain the next action and where to find help.'],
    ['Bekreft status fra backend. Gavekortet i ReAI sin testbutikk har eksplisitt manuell innløsning.','Verify status from the backend. The ReAI test-store gift card has explicit manual redemption.'],
    ['Labens ordre-ID og leveringsdato er illustrative og oppretter ingen e-post eller ordre.','The lab order ID and delivery dates are illustrative and create no email or order.'],
    [['Simuler sending: se varelinje, frakt og total i bekreftelsen.','Simulate shipping: see item, shipping and total in confirmation.'],['Simuler faktura: se ubetalt, ikke betalt.','Simulate invoice: see unpaid rather than paid.'],['Kontroller at avventer forklarer neste steg uten ny belastning.','Check pending explains next steps without another charge.']],['after-purchase','order-tracking']),
  a('order-tracking','after-purchase','tracking','checkout',
    ['Ordresporing: skille klargjøring, sendt og levert','Order tracking: distinguish preparation, shipped and delivered'],
    ['Vis status og tidspunkt fra riktig kilde. En fraktetikett betyr ikke at transportøren har mottatt pakken.','Show status and timestamps from the appropriate source. A shipping label does not mean the carrier received the parcel.'],
    ['Kunden kan lese opprettet sending som sendt og begynne å lete etter en pakke som ikke er overlevert.','Shoppers may interpret a created shipment as shipped and look for a parcel not yet handed over.'],
    ['Vis sporingslenke, leveringsestimat og hjelp når informasjonen finnes. Forklar delsendte ordre per sending.','Show tracking links, delivery estimates and help when available. Explain partial fulfillment per shipment.'],
    ['Fraktintegrasjon og ordrestatus eies av backend. En offentlig ordreside trenger sikker tilgang, ikke en gjettbar ID.','Shipment integration and order state belong to the backend. A public order page needs secure access, not a guessable ID.'],
    ['Laben viser bekreftelse, ikke en live sporingsportal eller transportørhendelser.','The lab shows confirmation, not a live tracking portal or carrier events.'],
    [['Kontroller at klargjøring ikke beskrives som sendt i labens neste steg.','Check preparation is not described as shipped in the lab next step.'],['I egen butikk: test én ordre med to separate sendinger.','In your store, test one order with two separate shipments.'],['Kontroller autorisasjon før ordredata vises på en offentlig lenke.','Verify authorization before showing order data through a public link.']],['confirmation-summary','support-contact']),
  a('support-contact','after-purchase','tracking','checkout',
    ['Kundeservice med ordrekontekst og riktig mottaker','Customer support with order context and the right recipient'],
    ['Fortell hvem som kan hjelpe med kjøpet og hvilken referanse kunden bør oppgi. Ikke send kunden til feil plattformkontakt.','Explain who can help with the purchase and which reference to include. Do not send shoppers to the wrong platform contact.'],
    ['En platform-logo kan få kunden til å spørre ReAI om butikkens leveringspraksis.','A platform logo can make shoppers ask ReAI about a merchant-specific delivery policy.'],
    ['Ha en vedlikeholdt kontaktvei ved bekreftelse og vilkår. Oppgi svartid bare når virksomheten kan holde den.','Maintain a contact route beside confirmation and policies. State response times only when the business can meet them.'],
    ['Selgeren håndterer produkt og levering. ReAI gavekort håndteres manuelt via post@reai.no etter bekreftet betaling.','The merchant handles product and delivery questions. ReAI gift cards are handled manually through post@reai.no after confirmed payment.'],
    ['Labens hjelpetekst er veiledning og sender ingen henvendelse.','Lab support copy is guidance and sends no message.'],
    [['Finn neste steg i den simulerte bekreftelsen.','Find the next step in simulated confirmation.'],['Les ekte gavekortvilkår og finn mottaker for innløsning.','Read real gift-card terms and find the redemption contact.'],['Ikke legg kortdata eller sensitive opplysninger i en e-postlenke.','Never put card details or sensitive information in an email link.']],['returns-process','after-purchase']),
  a('returns-process','after-purchase','returns','product',
    ['Returprosessen: valg, kostnad og faktisk status','Return process: choices, cost and actual status'],
    ['Forklar hvordan kunden starter en retur, hvilke varer som gjelder og hva som skjer videre. En forespørsel er ikke en refusjon.','Explain how to start a return, eligible items and next steps. A request is not a refund.'],
    ['En generisk kontakt oss-lenke kan skjule både returkostnad og hvilke opplysninger selgeren trenger.','A generic contact-us link can hide both return costs and the information the merchant needs.'],
    ['Velg manuell prosess hvis det passer virksomheten. En selvbetjent portal krever autentisering og oppfølging, ikke bare et skjema.','Choose a manual process if it fits the business. A self-service portal needs authentication and follow-up, not merely a form.'],
    ['Ordrelinjer, refusjon og kreditering er backend-handlinger. Vilkårene må samsvare med produkt og faktisk praksis.','Order lines, refunds and credits are backend actions. Policies must match the product and actual practice.'],
    ['Produktlaben har kun merkede vilkårseksempler, ingen retur- eller refusjonsservice.','The product lab contains labeled policy examples only, not a returns or refund service.'],
    [['Åpne vilkår ved produktet og finn spørsmål om kostnad og fremgangsmåte.','Open product policies and find cost and procedure questions.'],['I egen prosess: skill forespurt, mottatt og refundert.','In your process, distinguish requested, received and refunded.'],['Test delretur uten å beskrive hele ordren som refundert.','Test a partial return without describing the whole order as refunded.']],['returns','support-contact']),
  a('consent-preferences','after-purchase','consent','learning',
    ['E-postvalg: samtykke, forventning og avmelding','Email preferences: consent, expectations and unsubscribe'],
    ['Skill ordremeldinger fra frivillig markedsføring. Forklar hva påmelding betyr før kunden velger den.','Separate transactional messages from optional marketing. Explain signup before the shopper chooses it.'],
    ['Et checkout-felt er ikke et ja til alle fremtidige kampanjer eller en lovet kupong.','A checkout email is not consent to future campaigns or a promised coupon.'],
    ['Bruk uavkrysset påmelding og fungerende avmelding. Frekvensvalg bør bare tilbys hvis utsendingene faktisk følger dem.','Use unchecked signup and working unsubscribe. Offer frequency preferences only when sends actually honor them.'],
    ['newsletter:subscribe og back-in-stock er forskjellige formål. En velkomstflyt må være konfigurert før den loves.','newsletter:subscribe and back-in-stock serve different purposes. Configure welcome flows before promising them.'],
    ['Eksemplene har samtykke for signup; et frekvenssenter er veiledning, ikke en aktiv ReAI-funksjon her.','Examples have signup consent; a frequency center is guidance, not an active ReAI feature here.'],
    [['Se påmeldingen uten å sende inn: valget skal ikke være avkrysset.','Inspect signup without submitting: consent must be unchecked.'],['Les personvern og identitet før en eventuell påmelding.','Read privacy and merchant identity before any signup.'],['I egen utsending: test avmelding og eventuelle frekvensvalg.','In your send flow, test unsubscribe and any frequency choices.']],['guest-email','after-purchase']),

  a('category-seo','seo','links','learning',
    ['Kategori-SEO som hjelper kunden å velge','Category SEO helps shoppers choose'],
    ['Gi en kategori en tydelig tittel og nyttig innledning. Forklar hva som skiller utvalget før du legger til mer tekst.','Give a category a clear title and useful introduction. Explain what distinguishes the selection before adding more text.'],
    ['En lang tekst med søkeord over varene kan gjøre kundens faktiske oppgave vanskeligere.','A long keyword passage above products can make the actual shopping task harder.'],
    ['Lag sider for vedlikeholdte kategorier med eget formål. Ikke opprett nesten identiske sider for hver formulering av samme behov.','Create maintained category pages serving distinct needs. Avoid nearly identical pages for every phrasing of the same need.'],
    ['ReAI leverer samlingsnavn og varer. Nettsiden kan legge til originale valgkriterier og internlenker.','ReAI provides collection names and items. The site can add original choice criteria and internal links.'],
    ['Læringsgruppene er indekserbare kategorier; fiktive varekolleksjoner er fortsatt noindex.','Learning groups are indexable categories; fictional merchandise collections remain noindex.'],
    [['Åpne en læringsgruppe og finn dens konkrete oppgave i tittelen.','Open a learning group and find its specific task in the title.'],['Finn en relevant artikkel via vanlige HTML-lenker.','Find a relevant article through standard HTML links.'],['Bytt språk og kontroller overskrift og beskrivelse.','Switch language and check heading and description.']],['seo','internal-links']),
  a('faceted-seo','seo','facets','learning',
    ['SEO for filtre: nyttige landingssider uten URL-eksplosjon','Filter SEO: useful landing pages without URL explosion'],
    ['Behandle ad hoc søk og filtre som arbeidsverktøy. Kurater egne landingssider når kombinasjonen har varig kundeverdi.','Treat ad hoc search and filters as task tools. Curate landing pages when combinations provide lasting shopper value.'],
    ['Farge × størrelse × pris × sortering kan produsere mange adresser med svært likt innhold.','Color × size × price × sorting can create many addresses with very similar content.'],
    ['Skille crawlbegrensning fra noindex. Hvis Google skal lese noindex, må adressen kunne crawles.','Distinguish crawl restrictions from noindex. If Google needs to read noindex, the URL must be crawlable.'],
    ['Den kuraterte sitemap-listen eies av nettstedet. Filter-URL-er i artikkelbiblioteket får noindex og ren canonical.','The site owns its curated sitemap. Filtered library URLs receive noindex and a clean canonical.'],
    ['Dette er et lite bibliotek. Store kataloger trenger egen crawlstrategi; canonical alene begrenser ikke alle crawls.','This is a small library. Large catalogs need a crawl strategy; canonical alone does not prevent every crawl.'],
    [['Søk i biblioteket: kontroller noindex på resultatadressen.','Search the library: check noindex on the results URL.'],['Åpne en artikkel: den skal ha egen indeksbar canonical.','Open an article: it should have its own indexable canonical.'],['Sjekk sitemap: ingen q-, group- eller designkombinasjoner.','Check the sitemap: no q, group or design combinations.']],['category-seo','seo']),
  a('product-seo','seo','urls','fashionProduct',
    ['Produktside-SEO: stabil identitet og korrekt informasjon','Product-page SEO: stable identity and accurate information'],
    ['En produktside trenger et beskrivende navn, stabil URL og riktig tilgjengelighet. Rik produktdata skal bygge på ekte varer.','A product page needs a descriptive name, stable URL and accurate availability. Rich product data must describe real products.'],
    ['En endret tittel bør ikke uten videre bryte lenker; fiktive stjerner skal aldri bli søkeresultatsignaler.','A changed title should not casually break links; fixture stars must never become search-result signals.'],
    ['Avklar variant-URL-strategi før publisering. Skill et midlertidig utsolgt produkt fra permanent fjernet produkt.','Define a variant URL strategy before publishing. Distinguish temporary unavailability from permanent removal.'],
    ['Produkt-ID er stabil i backend. Nettstedet eier slug, redirects og eventuell verifisert Product-schema.','The backend product ID is stable. The site owns slugs, redirects and any verified Product schema.'],
    ['Testproduktsidene er noindex og har ingen oppdiktet Product eller AggregateRating-schema.','Fixture product pages are noindex and publish no invented Product or AggregateRating schema.'],
    [['Åpne en fashion-vare og kontroller lesbar URL og H1.','Open a fashion item and inspect readable URL and H1.'],['Kontroller noindex selv med variantparameter.','Check noindex even with a variant parameter.'],['I ekte butikk: test gamle lenker etter navneendring.','In a real store, test old links after a name change.']],['variant-images','image-seo']),
  a('internal-links','seo','links','learning',
    ['Internlenker som forklarer neste relevante oppgave','Internal links explain the next relevant task'],
    ['Bruk beskrivende lenketekst mellom kategori, artikkel og eksempel. Et klikk skal føre til innhold som faktisk løser oppgaven.','Use descriptive links between categories, articles and examples. Clicking should reach content that actually addresses the task.'],
    ['Les mer gjentatt overalt gjør det vanskelig å skille lenker ved skanning eller hjelpeteknologi.','Repeated read-more labels make links hard to distinguish when scanning or using assistive technology.'],
    ['Prioriter relevante sammenhenger fremfor å lenke hver side til alt. Behold brødsmulesti og en vei tilbake.','Prioritize relevant relationships rather than linking everything to everything. Keep breadcrumbs and a return route.'],
    ['Læringsbiblioteket bruker vanlige server-renderte lenker. ReAI data trenger ingen JS-only navigasjon.','The learning library uses standard server-rendered links. ReAI data does not require JS-only navigation.'],
    ['Lenkene forbedrer navigasjon; de lover ingen bestemt Google-rangering.','Links improve navigation; they promise no particular Google ranking.'],
    [['Finn variantredigering fra kurvartikkelen.','Find variant editing from the cart article.'],['Åpne produktlab og returner til den relevante forklaringen.','Open the product lab and return to its relevant explanation.'],['Deaktiver JS: artikkel- og gruppelenker skal fortsatt virke.','Disable JS: article and group links should still work.']],['category-seo','breadcrumbs']),
  a('image-seo','seo','images','fashionProduct',
    ['Bilde-SEO: beskrivelse, størrelse og riktig format','Image SEO: descriptions, dimensions and appropriate formats'],
    ['Bruk relevante bilder med beskrivende alt-tekst og plass i layouten. Filformat skal støtte kvalitet og lasting, ikke fylle et søkeordkrav.','Use relevant images with descriptive alt text and reserved layout space. Formats should support quality and loading, not keyword quotas.'],
    ['Samme generiske alt på alle farger gjør bilder mindre nyttige. Et stort originalbilde kan bremse mobil.','Identical generic alt across colors reduces usefulness. A large original image can slow mobile loading.'],
    ['Alt beskriver bildet der det gir mening; dekorative bilder trenger ingen oppdiktet produktforklaring.','Alt describes meaningful image content; decorative images need no invented product explanation.'],
    ['Bruk publiserte bilder og dokumenterte rettigheter. Responsive størrelser og prioritet styres i frontend.','Use published images and documented rights. Responsive sizes and loading priorities belong to the frontend.'],
    ['Famme-foto er autorisert testmateriale, ikke generiske MIT-ressurser.','Famme photographs are authorized test material, not generic MIT resources.'],
    [['Bytt farge: hovedbildets alt skal følge fargen.','Change color: main-image alt should follow the color.'],['Se på mobil og kontroller at bildet ikke skaper horisontal overflow.','Inspect mobile and check the image causes no horizontal overflow.'],['Kontroller at bilder etter første viewport ikke alle lastes med høyeste prioritet.','Check below-the-fold images are not all given highest priority.']],['performance','variant-images']),
  a('pagination-seo','seo','pages','learning',
    ['Paginering: lenker som virker uten klikkende crawler','Pagination: links that work without a clicking crawler'],
    ['Hvis produkter eller artikler deles i sider, skal hver side kunne nås med en vanlig URL og lenke.','When products or articles span pages, each page needs a standard URL and link.'],
    ['En crawler klikker ikke nødvendigvis en last mer-knapp eller skroller en uendelig liste.','A crawler does not necessarily click load-more or scroll an infinite list.'],
    ['Server-render komplette små lister. Store lister kan kombinere brukerinitiert lasting med stabile sideadresser.','Server-render complete small lists. Large lists can combine user-initiated loading with stable page URLs.'],
    ['API-paginering og sidens URL-er er ulike kontrakter. Definer hvordan begge kan gjenopprettes og lenkes.','API pagination and page URLs are different contracts. Define restoration and linking for both.'],
    ['Artikkelbiblioteket rendrer alle treff; det trenger ikke JS eller ekstra sider for å eksponere artiklene.','The article library renders all matches; it needs no JS or extra pages to expose articles.'],
    [['Les bibliotekets HTML og finn artikkellenker.','Read library HTML and find article links.'],['Åpne en direkte artikkel-URL uten først å besøke huben.','Open a direct article URL without first visiting the hub.'],['Ved egen paginering: test side 2 direkte og tilbake fra en vare.','For your pagination, test page two directly and return from an item.']],['load-more-return','internal-links']),

  a('funnel-definition','cro','experiments','measurement',
    ['Kjøpstrakt med tydelig nevner og bekreftet utfall','Commerce funnels with explicit denominators and confirmed outcomes'],
    ['Definer hvert steg som en observerbar hendelse. Skill et forsøk på checkout fra akseptert ordre og bekreftet betaling.','Define each step as an observable event. Separate a checkout attempt from an accepted order and confirmed payment.'],
    ['Hvis alle besøk er nevner, kan endret trafikk se ut som checkout-forbedring.','Using all visits as the denominator can make traffic changes resemble checkout improvement.'],
    ['Velg en nevner som passer endringen, for eksempel kvalifiserte produktbesøk. Dedupliser kunder, ordre og betalingshendelser bevisst.','Choose a denominator fitting the change, such as eligible product visits. Deliberately deduplicate shoppers, orders and payment events.'],
    ['Frontend kjenner eksponering; ReAI/backend kjenner ordre og betaling. B2B kredittordre trenger egen utfallsdefinisjon.','Frontend knows exposure; ReAI/backend knows orders and payments. B2B credit orders need their own outcome definition.'],
    ['Arbeidsarket er en plan uten installert sporing eller ekte traktdata.','The worksheet is a plan without installed tracking or actual funnel data.'],
    [['Skriv primærmålingen med teller og nevner.','Write the primary metric with numerator and denominator.'],['Forklar hvordan testordre og duplikate webhooks holdes utenfor.','Explain exclusion of test orders and duplicate webhooks.'],['Lag separate definisjoner for betalt og kredittordre.','Create separate definitions for paid and credit orders.']],['experiments','experiment-guardrails']),
  a('experiment-segmentation','cro','experiments','measurement',
    ['Eksperimentmålgruppe før resultater deles opp','Experiment audiences before splitting results'],
    ['Definer hvem endringen gjelder før testen starter. Mobil, marked og ny kunde kan være relevante segmenter, men etterpåjakt skaper falske vinnere.','Define eligibility before starting. Mobile, market and new shoppers can be useful segments, but post-hoc hunting creates false winners.'],
    ['Et tilfeldig positivt undersegment kan oppstå når mange segmenter undersøkes samtidig.','A random positive subgroup can appear when many segments are inspected simultaneously.'],
    ['Ha en primær analyse og få begrunnede segmenter. Undersøk andre mønstre som hypoteser for senere arbeid.','Use a primary analysis and a few justified segments. Treat other patterns as hypotheses for later work.'],
    ['Eksponering må registreres stabilt og respektere personvern. Ikke bytt testvariant ved hver sidevisning.','Record exposure consistently and respect privacy. Do not reassign variants on every page view.'],
    ['Arbeidsarket foreslår målgruppe; nettstedet foretar ingen randomisering.','The worksheet suggests an audience; the site performs no randomization.'],
    [['Skriv målgruppen før du fyller beslutningsregelen.','Write eligibility before completing the decision rule.'],['Beskriv om deltaker eller session er fordelingsenheten.','Describe whether allocation uses shoppers or sessions.'],['Merk nye segmentfunn som hypoteser, ikke bekreftede gevinster.','Label new segment findings as hypotheses rather than confirmed gains.']],['experiments','sample-ratio-mismatch']),
  a('sample-ratio-mismatch','cro','experiments','measurement',
    ['Skjev testfordeling: sjekk SRM før du tolker effekt','Allocation imbalance: check SRM before interpreting effects'],
    ['Kontroller om observerte deltakertall stemmer med planlagt fordeling. Uforklart avvik kan gjøre et eksperiment upålitelig.','Check observed participant counts against planned allocation. Unexplained imbalance can make an experiment unreliable.'],
    ['En variant som feiler før eksponeringslogging, kan se bedre ut fordi feilbrukere forsvinner fra datasettet.','A variant failing before exposure logging may look better because affected shoppers disappear from the dataset.'],
    ['Registrer datakvalitetskontroller før effektanalyse. Ikke reparer fordelingen ved å droppe vanskelige rader etterpå.','Plan data-quality checks before effect analysis. Never repair allocation by dropping inconvenient rows afterward.'],
    ['Logg tildeling, eksponering og feil som forskjellige hendelser med en avtalt enhet.','Log assignment, exposure and failures as distinct events using an agreed unit.'],
    ['Siden regner ingen SRM-test og mottar ingen eksperimentdata.','The site calculates no SRM test and receives no experiment data.'],
    [['Skriv forventet fordeling og hvilke hendelser den gjelder.','Write the expected allocation and applicable events.'],['List årsaker som botfilter, loggingfeil og variantkrasj.','List causes such as bot filtering, logging failure and variant crashes.'],['Bestem at uforklart datakvalitetsavvik blokkerer vinnerpåstand.','Decide that unexplained quality issues block winner claims.']],['experiment-segmentation','experiment-guardrails']),
  a('experiment-guardrails','cro','experiments','measurement',
    ['CRO-kvalitetsgrenser: margin, returer og feil','CRO guardrails: margin, returns and errors'],
    ['Mål mer enn gjennomførte kjøp. En endring som øker feil, retur eller rabattkostnad kan skade virksomheten.','Measure more than completed purchases. A change increasing errors, returns or discount cost can harm the business.'],
    ['En aggressiv rabatt kan øke ordretall uten å forbedre kundeverdi eller lønnsomhet.','An aggressive discount can increase orders without improving shopper value or profitability.'],
    ['Velg få begrunnede kvalitetsgrenser og en tilstrekkelig oppfølgingstid. Ikke lov raske konklusjoner ved lav trafikk.','Choose a few justified guardrails and adequate follow-up. Never promise quick conclusions with low traffic.'],
    ['Backend gir bekreftede refusjoner og ordre; kostnad og margin krever passende forretningsdata.','The backend supplies confirmed refunds and orders; costs and margins require appropriate business data.'],
    ['Arbeidsarket strukturerer en plan, ikke en automatisk anbefaling om å lansere endringen.','The worksheet structures a plan, not an automatic recommendation to launch a change.'],
    [['Beskriv ønsket utfall og én mulig skade fra samme endring.','Describe the desired outcome and one possible harm from the change.'],['Definer hvordan refusjoner knyttes til opprinnelig ordre.','Define how refunds link to the original order.'],['Skriv beslutningsregelen før resultater og midlertidige topper vises.','Write the decision rule before results or temporary spikes appear.']],['funnel-definition','experiments']),

  a('keyboard-dialogs','accessibility','dialog','fashionProduct',
    ['Dialoger: tastatur, Escape og tilbakeført fokus','Dialogs: keyboard access, Escape and focus return'],
    ['Åpning skal flytte fokus inn i dialogen, og lukking skal føre kunden tilbake til en meningsfull kontroll.','Opening should move focus into the dialog; closing should return shoppers to a meaningful control.'],
    ['En kurv som bare kan lukkes med mus, eller fokus bak dialogen, bryter kjøpsoppgaven.','A mouse-only cart close action or focus behind a modal interrupts shopping.'],
    ['Native dialog hjelper med modalitet. Kontroller fortsatt navn, startfokus, synlig lukking og nestede dialoger.','Native dialog helps with modality. Still verify naming, initial focus, visible closing and nested dialogs.'],
    ['Frontend eier dialog og fokus. Ingen backend-integrasjon erstatter tilgjengelige kontroller.','Frontend owns dialog and focus behavior. Backend integration cannot replace accessible controls.'],
    ['Fashion-kurv, variantredigering, størrelse og bildezoom er ekte interaksjoner med fixture-data.','Fashion cart, variant editing, sizing and image zoom are working interactions with fixture data.'],
    [['Åpne zoom med tastatur og flytt mellom kontrollene.','Open zoom by keyboard and move between controls.'],['Trykk Escape og kontroller åpneren som fokuspunkt.','Press Escape and check the opener receives focus.'],['Åpne størrelsesguide fra variantredigering: lukking skal returnere til riktig dialog.','Open sizing from variant editing: closing should return to the correct dialog.']],['drawer-checkout','image-zoom-mobile']),
  a('accessible-forms','accessibility','accessible','checkout',
    ['Tilgjengelige skjema med feltfeil og feilsammendrag','Accessible forms with field errors and error summaries'],
    ['Knytt label og feiltekst til feltet. Gi et sammendrag som peker til feilen, og behold gyldige opplysninger.','Associate labels and errors with fields. Provide a summary linking to errors and retain valid information.'],
    ['Rød ramme alene forklarer verken hva som er feil eller hvordan kunden retter det.','A red border alone explains neither the problem nor its correction.'],
    ['Vis feil etter at kunden har hatt mulighet til å fylle feltet. Fjern feiltilstand når teksten er rettet.','Show errors after shoppers have had a chance to complete the field. Remove error state after correction.'],
    ['Frontend kan gi formatfeedback. Serverfeil skal presenteres med like tydelig sammenheng og uten å nullstille skjemaet.','Frontend can provide format feedback. Present server errors with equally clear context without resetting the form.'],
    ['Laben har feltfeedback etter blur og et lenket sammendrag ved innsending.','The lab provides feedback after blur and a linked summary on submission.'],
    [['Skriv feil e-post og forlat feltet: se koblet feilmelding.','Enter invalid email and leave the field: see its associated error.'],['Rett e-posten: feilteksten skal forsvinne.','Correct email: remove the error text.'],['Send et ufullstendig skjema: bruk feilsammendragets lenke til feltet.','Submit an incomplete form: follow an error-summary link to its field.']],['errors','optional-fields']),
  a('reduced-motion','accessibility','motion','fashionProduct',
    ['Redusert bevegelse uten å miste tilbakemelding','Reduced motion without losing feedback'],
    ['Respekter redusert bevegelse for scrolling og ikke-essensielle overganger. Kunden skal fortsatt se hva som endret seg.','Respect reduced motion for scrolling and nonessential transitions. Shoppers should still perceive state changes.'],
    ['Et raskt scrollhopp eller stor zoomanimasjon kan være plagsomt selv når innholdet er riktig.','Fast scrolling or large zoom animation can be uncomfortable even when content is correct.'],
    ['Bruk tekst og tydelig tilstand som primær feedback. Bevegelse bør være et valgfritt supplement.','Use text and clear state as primary feedback. Motion should be an optional supplement.'],
    ['Frontend og operativsystemets preferanse styrer bevegelse; det finnes ingen tenantinnstilling som må opprettes.','Frontend and the operating-system preference control motion; no tenant setting needs creation.'],
    ['Design og læringsflater har en prefers-reduced-motion-regel. Det er ingen full tilgjengelighetssertifisering.','Design and learning surfaces include a prefers-reduced-motion rule. This is not accessibility certification.'],
    [['Slå på redusert bevegelse og åpne kurven.','Enable reduced motion and open the cart.'],['Velg et produkt i laben: fakta skal vises uten påtvunget smooth scroll.','Choose a lab product: show facts without forced smooth scrolling.'],['Kontroller at valgt variant fortsatt markeres tydelig.','Check that the selected variant remains clearly indicated.']],['performance','keyboard-dialogs']),
  a('touch-targets','accessibility','touch','fashionProduct',
    ['Trykkflater for farger, størrelser og kurvkontroller','Touch targets for colors, sizes and cart controls'],
    ['Gi små valg nok trykkflate og avstand. Den synlige fargeprøven kan være liten mens knappen er større.','Give small choices sufficient hit area and spacing. A visible swatch may be small while its button is larger.'],
    ['To tettliggende farger kan bli feil variant når kunden trykker med tommel.','Closely spaced swatches can select the wrong variant when tapped with a thumb.'],
    ['Mål klikkflaten, ikke bare ikonet. WCAG-minimum og unntak er ikke et argument for å gjøre viktige valg så små som mulig.','Measure the target, not just its icon. WCAG minimums and exceptions are no reason to minimize important controls.'],
    ['CSS og semantiske knapper eies av nettstedet. Et navn og tydelig valgt tilstand må følge den større flaten.','CSS and semantic buttons belong to the site. Labels and clear selection state must accompany larger targets.'],
    ['Swatches, størrelser, zoom og variantredigering har romslige kontroller; hele nettstedet er ikke auditert mot WCAG.','Swatches, sizes, zoom and variant edits have spacious controls; the whole site has not been audited against WCAG.'],
    [['Ved 390 px: velg nabofarger og kontroller riktig variant.','At 390 px, select adjacent colors and check the correct variant.'],['Mål knappen rundt fargeprøven, ikke bare prikken.','Measure the button around the swatch rather than just the dot.'],['Test med tastatur og zoom: større trykkflate skal ikke skjule label.','Test keyboard and zoom: larger targets must not hide labels.']],['variant-names','mobile-navigation']),
];
